import {profileStats} from './mentor-core.mjs';
export async function initMentors(root=document){
const el=(tag,value)=>{const x=document.createElement(tag);x.textContent=value||'';return x;},$=s=>root.querySelector(s);
const link=(label,url)=>{const a=el('a',label);try{if(new URL(url).protocol==='https:'){a.href=url;a.target='_blank';a.rel='noopener noreferrer';}}catch{}return a;};
let people=[];const initial=new URLSearchParams(location.search).get('q')||'';$('#query').value=initial;
function draw(){const q=$('#query').value.trim().toLowerCase();$('#people').replaceChildren();for(const p of people.filter(p=>JSON.stringify([p.name,p.institution,p.department,p.topics]).toLowerCase().includes(q))){const card=el('article'),stats=profileStats(p);card.id=p.id;card.append(el('h2',p.name),el('p',p.institution+' · '+p.department),el('p',p.position+' · 官方身份已核对 '+p.verifiedAt),link('官方主页 ↗',p.officialUrl));const save=el('button','收藏导师（本浏览器）');save.onclick=()=>{try{const ids=JSON.parse(localStorage.getItem('np-mentors')||'[]');localStorage.setItem('np-mentors',JSON.stringify([...new Set([...ids,p.id])]));save.textContent='已收藏';}catch{save.textContent='保存失败：浏览器存储不可用';}};card.append(save,el('h3','官方页面介绍的研究方向'),el('p',(p.topics||[]).join(' · ')),el('small','官方描述，不是最近五年的论文统计，也不代表招生方向。'),el('h3','近期主题、年度成果与合作'),el('p',stats.notice));if(stats.annual){for(const y of stats.annual)card.append(el('p',`${y.year}${y.partial?'（未完整年度）':''}：${y.works.length} 项`));for(const t of stats.topics)card.append(el('p',t.label+' · '+t.basis+' · 依据 '+t.works.join(', ')));for(const c of stats.collaborators)card.append(el('p',c.name+' · 共同论文 '+c.works.join(', ')));for(const w of stats.works){card.append(link(w.title,w.url||w.doi),el('small',w.id+' · '+w.type+' · '+w.year));const report=el('a','论文归属有误？');report.href='feedback.html?object='+encodeURIComponent('work:'+w.id);card.append(report);}}
 card.append(el('p',p.summary),el('h3','已公开且已核对的培养与去向案例'),el('p',(p.training||[]).length?'详见下方证据':'暂无完成核对的案例；不把合作者当学生，不推断毕业生去向。'),el('h3','申请前待确认'),el('p',p.application?.note||'当前招生、资助、指导资格、语言与到岗时间：未知。请查具体公告，主页存在不代表正在招生。'));
 const details=el('details');details.append(el('summary','来源、核验范围与外部身份'));for(const e of p.evidence||[]){details.append(link(e.field+' · '+e.observedAt,e.url),el('blockquote',e.excerpt));}details.append(el('pre',JSON.stringify({externalIds:p.externalIds,sync:p.sync},null,2)));card.append(details);const feedback=el('a','纠错或补充：身份、主题与关系');feedback.href='feedback.html?object='+encodeURIComponent('mentor:'+p.id);card.append(feedback);$('#people').append(card);}$('#status').textContent=`已登记 ${people.length} 位官方身份；结果 ${$('#people').children.length} 位。统计同步状态逐人列出。`;}
$('#query').oninput=draw;try{let r=await fetch('/api/mentors');if(r.status===404)r=await fetch('mentor-pilot.json');if(!r.ok)throw Error();people=(await r.json()).mentors;draw();}catch{$('#status').textContent='导师资料加载失败，请重试。不是零位导师。';}
}
if(document.querySelector('body>main>#people'))location.replace('./?panel=mentor');
